        // Reduce along dimension 2 (dim2)
        half max_val = input[batch_idx * dim1 * dim2 + dim1_idx * dim2];
        int max_idx = 0;

        for (int i = 1; i < dim2; i++) {
            half val = input[batch_idx * dim1 * dim2 + dim1_idx * dim2 + i];
            if (__hgt(val, max_val)) {
                max_val = val;
                max_idx = i;
            }
        }
        output[output_idx] = max_idx;
    } else if (dim_to_reduce == 1) {
        // Reduce along dimension 1 (dim1)
        half max_val = input[batch_idx * dim1 * dim2 + i * dim2];
        int max_idx = 0;

        for (int i = 1; i < dim1; i++) {
            half val = input[batch_idx * dim1 * dim2 + i * dim2];
            if (__hgt(val, max_val)) {
                max_val = val;
                max_idx = i;
            }
        }
        output[output_idx] = max_idx;
    }
}

// Optimized version for better memory access patterns
__global__ void argmax_kernel_optimized(
    const half* input,
    int* output,
    int total_elements,
    int dim_to_reduce,
    int stride,
    int num_reductions
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= num_reductions) return;

    half max_val = input[idx * stride];
    int max_idx = 0;

    for (int i = 1; i < stride; i++) {
        half val = input[idx * stride + i];
        if (__hgt(val, max_val)) {
            max_val = val;
            max_idx = i;
        }
    }
    output[idx] = max_idx;
}
"""

