                block_size = 256
                grid_size = (num_reductions + block_size - 1) // block_size

                module.argmax_kernel_optimized(
                    x.data_ptr(),
                    output.data_ptr(),
                    batch_size * dim2,
                    1,
                    dim1,
                    num_reductions
                )

                return output.view(batch_size, dim2)
